def test_index_not_in_source_proof_fails(self):
    keep = (1, 2)
    sparse = multiproof_encode(
        self.public_key,
        tuple(
            __import__("pqattest").MerkleSignature(
                index=i,
                wots_signature=s.wots_signature,
                auth_path=s.auth_path,
            )
            for i, s in enumerate(
                __import__("pqattest").MerkleSigner.from_seed(
                    b"\x07" * 32, height=2, w=4
                ).sign_batch(self.messages)
            )
            if i in keep
        ),
    )
    # Build a sparse proof honestly instead: sign a fresh signer.
    signer = make_signer(height=2)
    signatures = signer.sign_batch(self.messages)
    sparse = multiproof_encode(
        signer.public_key, (signatures[1], signatures[2])
    )
    sparse_messages = (self.messages[1], self.messages[2])

